-- 000001: AutoPanel's store on PostgreSQL. The tables, keys and checks are the
-- SQLite engine's 000001, with these translations:
--   - INTEGER PRIMARY KEY AUTOINCREMENT: bigint GENERATED BY DEFAULT AS IDENTITY,
--     which never reuses a value, as AUTOINCREMENT promises.
--   - INTEGER: bigint, the int64 every reader scans. BLOB: bytea.
--   - TEXT: text COLLATE "C", so text compares byte by byte, as SQLite's does.
-- The tables are created in the first schema of the connection's search_path
-- (the deployment's "autopanel" schema).

CREATE TABLE IF NOT EXISTS setting (
  key        text COLLATE "C" PRIMARY KEY,
  value      text COLLATE "C" NOT NULL,
  updated_at bigint NOT NULL
);

CREATE TABLE IF NOT EXISTS route (
  id          bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  host        text COLLATE "C" NOT NULL,
  path_prefix text COLLATE "C" NOT NULL DEFAULT '/',
  upstream    text COLLATE "C" NOT NULL,
  created_at  bigint NOT NULL,
  updated_at  bigint NOT NULL,
  UNIQUE (host, path_prefix),
  CHECK (host <> '' AND host = lower(host)),
  CHECK (substr(path_prefix, 1, 1) = '/')
);

CREATE TABLE IF NOT EXISTS audit (
  id      bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  at      bigint NOT NULL,
  actor   text COLLATE "C" NOT NULL,
  action  text COLLATE "C" NOT NULL,
  subject text COLLATE "C" NOT NULL,
  detail  text COLLATE "C" NOT NULL DEFAULT ''
);
CREATE INDEX IF NOT EXISTS audit_at ON audit (at, id);

CREATE TABLE IF NOT EXISTS cert_blob (
  key         text COLLATE "C" PRIMARY KEY,
  value       bytea NOT NULL,
  modified_at bigint NOT NULL
);

CREATE TABLE IF NOT EXISTS store_lease (
  id         bigint PRIMARY KEY CHECK (id = 1),
  holder     text COLLATE "C" NOT NULL,
  started_at bigint NOT NULL,
  renewed_at bigint NOT NULL
);

CREATE TABLE IF NOT EXISTS app_user (
  id         bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name       text COLLATE "C" NOT NULL UNIQUE,
  created_at bigint NOT NULL,
  CHECK (name <> '')
);

CREATE TABLE IF NOT EXISTS keyslot (
  id         bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  kind       text COLLATE "C" NOT NULL,
  user_id    bigint REFERENCES app_user(id) ON DELETE CASCADE,
  slot       text COLLATE "C" NOT NULL,
  created_at bigint NOT NULL,
  CHECK (kind IN ('passphrase', 'service')),
  CHECK ((kind = 'passphrase') = (user_id IS NOT NULL))
);
CREATE UNIQUE INDEX IF NOT EXISTS keyslot_passphrase_user ON keyslot (user_id) WHERE kind = 'passphrase';
CREATE UNIQUE INDEX IF NOT EXISTS keyslot_one_service ON keyslot (kind) WHERE kind = 'service';

CREATE TABLE IF NOT EXISTS secret (
  name       text COLLATE "C" PRIMARY KEY,
  value      bytea NOT NULL,
  updated_at bigint NOT NULL
);
